<?php declare(strict_types=1); ?>
<?php if($role||isset($_GET['new_role'])||input($_POST,'action')==='settings-role'): ?><form method="post" class="card settings-form" id="role-edit" data-role-editor><?= csrf().hidden('action','settings-role').hidden('role_id',$edit).hidden('version',$rv) ?><h2 tabindex="-1" autofocus><?= $role?'Rolle bearbeiten':'Neue Rolle erstellen' ?></h2><div class="form-grid"><?php settingsField('name',['Rollenname','text',100,'',true],$rd);settingsField('description',['Beschreibung','textarea',1000,''],$rd); ?></div><div class="table-scroll"><table class="table permissions-table"><thead><tr><th>Bereich</th><th>Sperren</th><th>Lesen</th><th>Bearbeiten</th></tr></thead><tbody><?php foreach(['members_access'=>'Mitglieder, Kontakte & Organisation','finance_access'=>'Finanzen, Spenden & Kassen','inventory_access'=>'Inventar & Lagerbestand','loans_access'=>'Ausleihen & Rückgaben','documents_access'=>'Allgemeine Orga-Dokumente','press_access'=>'Pressemitteilungen & Presseempfänger','minutes_access'=>'Protokolle für Mitglieder'] as $field=>$label): ?><tr><th><?= $label ?></th><?php foreach(['none'=>'Sperren','read'=>'Lesen','write'=>'Bearbeiten'] as $key=>$text): ?><td><input class="check" type="radio" name="data[<?= $field ?>]" value="<?= $key ?>" <?= $rd[$field]===$key?'checked':'' ?> aria-label="<?= e($label.': '.$text) ?>"></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div><?php settingsField('settings_access',['Vereinseinstellungen und Rollen verwalten','checkbox',1,false],$rd); ?><details class="role-editor-help"><summary>Hinweise zu Rechten</summary><p class="muted">Wer Rollen verwaltet, kann Rechte vergeben. Mindestens ein aktiver Zugang muss diese Berechtigung behalten. Lesen erlaubt keine Änderungen.</p></details><?php $websiteCustom=isset($rd['website_custom'])?(bool)$rd['website_custom']:(($rd['website_access']??null)!==null);$websiteMatrix=$rd['website_levels']??(($rd['website_access']??null)!==null?json_decode($rd['website_access'],true):[]); ?><h3>Website-Bereiche getrennt freigeben</h3><?= hidden('data[website_custom]','0') ?><label><input class="check" type="checkbox" name="data[website_custom]" value="1" <?= $websiteCustom?'checked':'' ?>> Eigene Bereichsfreigaben verwenden</label><details class="role-editor-help"><summary>Hinweise zu Rechten</summary><p>Wenn Sie eine Freigabe ändern, wird „Eigene Bereichsfreigaben“ automatisch aktiviert. Wenn Sie das Häkchen ausschalten, zeigt die Auswahl wieder die Voreinstellungen dieser Vereinsrolle. Konten mit der Grundrolle Redaktion und Superuser können zusätzliche Website-Grundrechte behalten oder wieder erhalten. Zum gezielten Sperren lassen Sie eigene Bereichsfreigaben eingeschaltet und wählen „Kein Zugriff“. Eine fehlende Website-Grundfreigabe wird dadurch nicht vergeben. Die tatsächlich nutzbaren Rechte sehen Sie unten beim jeweiligen Konto. Technische Website-Verwaltung bleibt ausschließlich beim technischen Administrator; zusätzliche native Website-Rechte werden nicht automatisch vergeben.</p></details><div class="table-scroll"><table class="table"><thead><tr><th>Bereich</th><th>Freigabe</th></tr></thead><tbody><?php foreach(\Kulturhus\Verein\EditorialPolicy::AREAS as $area=>$label):$level=$websiteMatrix[$area]??\Kulturhus\Verein\EditorialPolicy::level($rd,$area); ?><tr><th><?= e($label) ?></th><td><select class="form-control" name="data[website_levels][<?= e($area) ?>]" aria-label="<?= e($label) ?>"><?php foreach(['none'=>'Kein Zugriff','read'=>'Ansehen','write'=>'Bearbeiten'] as $value=>$label2): ?><option value="<?= $value ?>" <?= $level===$value?'selected':'' ?>><?= e($label2) ?></option><?php endforeach ?></select></td></tr><?php endforeach ?></tbody></table></div><p data-role-editor-status role="status"></p><div class="settings-actions"><a class="btn btn-outline theme-secondary button secondary" href="?view=settings&amp;tab=roles">Abbrechen</a><button class="btn btn-solid theme-primary">Rolle speichern</button></div></form><?php endif ?>
